def make_record(item: tuple, lang: str) -> dict:
    key = 1 if lang == "en" else 7
    return {
        "id": item[0],
        "question": item[key],
        "options": item[key + 1],
        "correct_answer": item[key + 2],
        "category": item[key + 3],
        "difficulty": "Hard",
        "bible_reference": item[key + 4],
        "explanation": item[key + 5],
    }


def main() -> None:
    for lang in ("en", "ne"):
        path = ROOT / "data" / f"questions_{lang}.json"
        records = json.loads(path.read_text(encoding="utf-8"))
        existing = {record["id"] for record in records}
        records.extend(make_record(item, lang) for item in QUESTIONS if item[0] not in existing)
        path.write_text(json.dumps(records, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Added 30 New Testament hard questions.")


if __name__ == "__main__":
    main()
